<?php
declare(strict_types=1);
namespace Brightery\Core\Ui;

/** Immutable fingerprinted asset URLs; manifest generated by bin/build-assets. */
final class AssetManager {
    private ?array $manifest=null;
    public function url(string $asset):string {
        if(!preg_match('~^[a-z0-9_./-]+$~D',$asset)||str_contains($asset,'..'))throw new \InvalidArgumentException('Invalid asset name');
        if($this->manifest===null){
            $path=base_path('public/assets/manifest.json');
            $data=is_file($path)?json_decode((string)file_get_contents($path),true):null;
            $this->manifest=is_array($data)?$data:[];
        }
        $url=$this->manifest[$asset]??'/assets/'.$asset;
        if(!is_string($url)||!str_starts_with($url,'/assets/')||str_contains($url,'..'))throw new \RuntimeException('Invalid asset manifest');
        return $url;
    }
}
